'use client';
import React,{useState} from 'react';
import {Plus,Download,Check,AlertCircle} from 'lucide-react';
import type {State,RecordRow as R} from '@/lib/erp-primitives';
import {day} from '@/lib/erp-primitives';
import {planningPeriods,planningProgress,planningActuals} from '@/lib/finance';
import {toCSV} from '@/lib/erp-ui';
const fmt=(n:number)=>new Intl.NumberFormat('en-UG',{maximumFractionDigits:0}).format(n||0);
function exportCSV(rows:any[],name:string){if(!rows.length)return;const u=URL.createObjectURL(new Blob([toCSV(rows)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name+'.csv';a.click();URL.revokeObjectURL(u)}
function Track({status}:{status:string}){return <span className={'finance-track '+(status==='Off track'?'attention':'')} aria-label={'Status: '+status}>{status==='On track'?<Check size={16}/>:status==='Off track'||status==='Incomplete'?<AlertCircle size={16}/>:null}{status}</span>}
export function FinancePlanForm({type,company,record,act,busy,onDirty,onClose,initial}:any){const today=day(),start=today.slice(0,7)+'-01',end=new Date(Date.UTC(Number(today.slice(0,4)),Number(today.slice(5,7)),0)).toISOString().slice(0,10),title=type==='budget'?'budget':'cash flow plan';
 const [form,setForm]=useState<any>(initial||record&&{...record}||{company:company==='Group'?'Hagadol':company,name:'',owner:'',periodStart:start,periodEnd:end,revenueTarget:'',costLimit:'',inflowTarget:'',outflowLimit:'',minimumCash:'',notes:''}),[dirty,setDirty]=useState(false),[error,setError]=useState('');
 const change=(key:string,value:any)=>{setForm((f:any)=>({...f,[key]:value}));setDirty(true);onDirty(true)};
 function cancel(){if(dirty&&!window.confirm('Discard unsaved plan changes?'))return;onDirty(false);onClose()}
 async function save(e:React.FormEvent){e.preventDefault();setError('');const result=await act(record?{action:'edit',id:record.id,expectedVersion:record.version,fields:form}:{action:'create',type,...form});if(result){onDirty(false);onClose()}else setError('The plan could not be saved. Check the workspace message and your entries.');}
 const money=(label:string,key:string)=><label>{label}<input required type="number" min="0" max="1000000000000" step="1" value={form[key]??''} onChange={e=>change(key,e.target.value)}/></label>;
 return <section className="panel finance-party-form"><header className="panelhead"><div><h2>{record?'Edit ':'New '}{title}</h2><p>Targets only. Saving a plan does not change your accounts.</p></div></header><form onSubmit={save}><div className="formgrid"><label>Business<select disabled={!!record} value={form.company} onChange={e=>change('company',e.target.value)}><option>Hagadol</option><option>WMK</option></select></label><label>Plan name<input required value={form.name} onChange={e=>change('name',e.target.value)}/></label><label>Owner<input required value={form.owner} onChange={e=>change('owner',e.target.value)}/></label><label>Period starts<input required type="date" value={form.periodStart} onChange={e=>change('periodStart',e.target.value)}/></label><label>Period ends<input required type="date" min={form.periodStart} value={form.periodEnd} onChange={e=>change('periodEnd',e.target.value)}/></label>{type==='budget'?<>{money('Revenue target UGX','revenueTarget')}{money('Operating cost limit UGX','costLimit')}</>:<>{money('Cash inflow target UGX','inflowTarget')}{money('Cash outflow limit UGX','outflowLimit')}{money('Minimum cash balance UGX','minimumCash')}</>}</div><label className="noteslabel">Planning notes<textarea rows={3} value={form.notes||''} onChange={e=>change('notes',e.target.value)}/></label><p className="footnote">Choose a month, quarter or another period up to one year. Targets are spread evenly by calendar day. Only one active plan of each type may cover a business on any date.</p>{error&&<p role="alert" className="notice">{error}</p>}<div className="dialogactions"><button className="secondary" type="button" disabled={busy} onClick={cancel}>Cancel</button><button className="primary" disabled={busy}>{busy?'Saving…':'Save '+title}</button></div></form></section>
}
export function FinancePlanning({state,company,type,cutoff,onDirty,act,busy,onDetail,onFormChange,initial={}}:{state:State;company:string;type:string;cutoff:string;onDirty:(v:boolean)=>void;act:(v:any)=>Promise<any>;busy:boolean;onDetail:(r:R)=>void;onFormChange:(v:boolean)=>void;initial?:any}){
 const [form,setForm]=useState<any>(initial.form||null),[periodId,setPeriodId]=useState(initial.period||'');const periods=planningPeriods(state.records,company,type),current=periods.find(p=>p.id===periodId)||periods.find(p=>p.start<=cutoff&&p.end>=cutoff)||periods[0],progress=current?planningProgress(state,company,current,type,cutoff):null,title=type==='budget'?'Budget':'Cash flow';
 const allPlans=state.records.filter(r=>r.type===type&&(company==='Group'||r.company===company)),plans=allPlans.filter(r=>r.status!=='Archived');
 function edit(record?:R){setForm({record});onFormChange(true)}function close(){setForm(null);onFormChange(false);onDirty(false)}
 const exported=progress?.rows.map(r=>({Business:company,PeriodStart:current!.start,PeriodEnd:current!.end,AsAt:progress.actual.cutoff,Metric:r.label,PeriodTargetUGX:r.target,ExpectedToDateUGX:r.expected,ActualUGX:r.actual,FavourableVarianceUGX:r.variance,Status:r.status,PlanStatus:progress.status}))||[];
 const actual=progress?.actual,monthlyStart=cutoff.slice(0,7)+'-01',monthlyEnd=new Date(Date.UTC(Number(cutoff.slice(0,4)),Number(cutoff.slice(5,7)),0)).toISOString().slice(0,10),unplannedActual=type==='cash_plan'&&!current?planningActuals(state,company,monthlyStart,monthlyEnd,cutoff):null,cash=actual||unplannedActual;
 const forecast=()=>cash&&<section className="panel"><header className="panelhead"><div><h2>Cash outlook to {current?.end||monthlyEnd}</h2><p>Based on unpaid posted invoices and bills. Overdue balances are assumed to settle during the remaining period.</p></div><button className="secondary" disabled={!cash.upcoming.length} onClick={()=>exportCSV(cash.upcoming.map(r=>({Business:r.company,Document:r.ref||r.name,Party:r.customer,Due:r.due,Type:r.type,ForecastAmountUGX:r.forecastAmount})),company+' Cash outlook')}>Export outlook</button></header><div className="minikpis"><span>Recorded cash<strong>UGX {fmt(cash.closing)}</strong></span><span>Expected receipts<strong>UGX {fmt(cash.receipts)}</strong></span><span>Expected bill payments<strong>UGX {fmt(cash.payments)}</strong></span><span>Projected cash<strong>UGX {fmt(cash.projectedCash)}</strong></span></div><div className="tablebox"><table className="finance-table"><thead><tr><th>Document</th><th>Business</th><th>Due</th><th>In / out</th><th>Remaining UGX</th></tr></thead><tbody>{cash.upcoming.map(r=><tr key={r.id}><td><button className="rowlink" onClick={()=>onDetail(state.records.find(x=>x.id===r.id)!)}>{r.ref||r.name}</button><small>{r.customer}</small></td><td>{r.company}</td><td>{r.due}</td><td>{r.type==='invoice'?'In':'Out'}</td><td>{fmt(r.forecastAmount)}</td></tr>)}</tbody></table>{!cash.upcoming.length&&<p className="empty">No dated unpaid documents in this outlook.</p>}</div>{cash.unscheduled.length>0&&<p className="notice">{cash.unscheduled.length} unpaid documents have no due date and are excluded from the projection. They remain visible in the document and ageing lists.</p>}<p className="footnote">This projection assumes full settlement. Unrecorded payroll, future loan repayments and other unbooked costs are excluded. Include them in your cash outflow target. {cutoff>=(current?.end||monthlyEnd)?'The period has ended. Projected cash equals its recorded closing balance.':''}</p></section>;
 if(form)return <FinancePlanForm type={type} company={company} record={form.record} act={act} busy={busy} onDirty={onDirty} onClose={close}/>;
 return <section className="finance-planning"><div className="sectiontoolbar"><div className="finance-plan-heading"><h2>{title} vs actual</h2><p>UGX · {company}</p></div>{current&&<label>Plan period<select value={current.id} onChange={e=>setPeriodId(e.target.value)}>{periods.map(p=><option value={p.id} key={p.id}>{p.start} to {p.end}</option>)}</select></label>}<button className="primary" disabled={busy} onClick={()=>edit()}><Plus size={15}/>New {type==='budget'?'budget':'cash flow plan'}</button><button className="secondary" disabled={!exported.length} onClick={()=>exportCSV(exported,company+' '+title+' vs actual')}><Download size={15}/>Export comparison</button></div>
 {!progress?<div className="empty"><h3>No {title.toLowerCase()} target set</h3><p>Create a plan for Hagadol or WMK to see On track and Off track indicators. Group combines the two business plans for matching dates.</p></div>:<><div className="finance-plan-summary"><Track status={progress.status}/><span>As at {progress.actual.cutoff} · {progress.pace.elapsed} of {progress.pace.duration} days</span></div>{current!.missing.length>0&&<p className="notice">Group plan incomplete: add a {title.toLowerCase()} plan for {current!.missing.join(' and ')} with the same dates. Combined targets remain incomplete until both businesses are covered.</p>}<p className="footnote">Expected to date uses an even daily share of the period target. {type==='budget'?'Revenue must reach that share and operating costs must stay within it.':'Cash inflow must reach that share and cash outflow must stay within it. Recorded and projected cash must meet the minimum cash target.'}</p><div className="tablebox"><table className="finance-table"><thead><tr><th>Metric</th><th>Period target UGX</th><th>Expected to date UGX</th><th>{type==='budget'?'Actual UGX':'Actual / projected UGX'}</th><th>Favourable variance UGX</th><th>Status</th></tr></thead><tbody>{progress.rows.map(r=><tr key={r.label}><td>{r.label}<small>{r.direction==='At most'?'Limit':'Target'}</small></td><td>{fmt(r.target)}</td><td>{fmt(r.expected)}</td><td>{fmt(r.actual)}</td><td>{fmt(r.variance)}</td><td><Track status={r.status}/></td></tr>)}</tbody></table></div>{type==='budget'?<div className="minikpis"><span>Planned operating result<strong>UGX {fmt(progress.plannedProfit)}</strong></span><span>Actual operating result<strong>UGX {fmt(actual!.profit)}</strong></span></div>:<div className="minikpis"><span>Opening recorded cash<strong>UGX {fmt(actual!.opening)}</strong></span><span>Actual net cash movement<strong>UGX {fmt(actual!.netCash)}</strong></span><span>Plan closing cash<strong>UGX {fmt(actual!.opening+progress.plannedNetCash)}</strong></span></div>}{progress.business.length>0&&<div className="finance-business-tracks">{progress.business.map(b=><div key={b.company}><strong>{b.company}</strong><Track status={b.status}/></div>)}</div>}{actual!.cons.unmatched.length>0&&company==='Group'&&<p className="notice">Unmatched internal documents remain in Group actuals. Review Group consolidation.</p>}</>}
 {type==='cash_plan'&&!progress&&cash&&<div className="minikpis"><span>Cash in this month<strong>UGX {fmt(cash.inflow)}</strong></span><span>Cash out this month<strong>UGX {fmt(cash.outflow)}</strong></span><span>Net movement<strong>UGX {fmt(cash.netCash)}</strong></span></div>}
 {type==='cash_plan'&&forecast()}
 <section className="panel"><header className="panelhead"><div><h2>Saved {title.toLowerCase()} plans</h2><p>Company targets are kept separate. Group combines plans with identical dates.</p></div></header><div className="tablebox"><table className="finance-table"><thead><tr><th>Plan</th><th>Business</th><th>Period</th><th>Owner</th><th>Status</th><th>Actions</th></tr></thead><tbody>{allPlans.map(p=><tr key={p.id}><td>{p.name}{p.notes&&<small>{p.notes}</small>}</td><td>{p.company}</td><td>{p.periodStart} to {p.periodEnd}</td><td>{p.owner}</td><td>{p.status}</td><td>{p.status!=='Archived'&&<><button className="textbutton" disabled={busy} onClick={()=>edit(p)}>Edit</button><button className="textbutton" disabled={busy} onClick={()=>{if(window.confirm('Archive this plan? Its targets will leave the active comparisons.'))act({action:'stage',id:p.id,expectedVersion:p.version,status:'Archived'})}}>Archive</button></>}</td></tr>)}</tbody></table>{!plans.length&&<p className="empty">No active plans for this business.</p>}</div></section><p className="footnote">Budget revenue excludes VAT; operating costs include recorded interest and exclude equipment and inventory purchases. Cash flow includes financing movements. Transfers within Bank, Cash and Mobile money are excluded. Group removes matched internal income, costs and settled cash transfers.</p>
 </section>
}
